import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Uploads = () => {
  const navigate = useNavigate();
  const [patientName, setPatientName] = useState("");
  const [patientId, setPatientId] = useState("");
  const [gender, setGender] = useState("Male");
  const [age, setAge] = useState("");
  const [date, setDate] = useState("");
  const [image, setImage] = useState(null);

  const handleImageChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setImage(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleScan = (e) => {
    e.preventDefault();
    if (!image) {
      alert("Please upload an image before scanning!");
      return;
    }
    navigate("/Analysis", {
      state: { patientName, patientId, gender, age, date, image },
    });
  };

  return (
    <div>    <div className="font-sans flex flex-col items-center">
      <h1 className="text-3xl font-bold text-darkblue mb-8 text-center">
        Upload Medical Image
      </h1>

      {/* Image Upload Section */}
      <div className="mb-8 flex flex-col items-center w-full max-w-md">
        {/* Upload Instructions */}
        <div className="text-center mb-4">
          <h2 className="text-xl font-bold text-white bg-darkblue p-3 rounded-t-md">
            Upload X-ray images
          </h2>
          <p className="text-white bg-darkblue p-2 rounded-b-md font-medium">
            upload single or multiple images to perform scanning
          </p>
        </div>

        {image ? (
          <img
            src={image}
            alt="Uploaded"
            className="w-full rounded-md border-2 border-dashed border-darkblue"
          />
        ) : (
          <div className="w-full h-64 border-2 border-dashed border-darkblue rounded-md bg-white flex flex-col items-center justify-center cursor-pointer hover:bg-gray-200 transition-colors relative">
            <label className="flex flex-col items-center justify-center w-full h-full cursor-pointer">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageChange}
                className="hidden"
                multiple
              />
              {/* Upload instruction text at the bottom */}
              <div className="absolute bottom-4 text-center">
                <p className="text-sky-400 font-medium">
                  Drag and drop or <span className="underline cursor-pointer">Choose image</span>
                </p>
              </div>
            </label>
          </div>
        )}
      </div>

      {/* Patient Information Section */}
      <div className="w-full max-w-md text-center mb-4">
        <h2 className="text-xl font-semibold text-darkblue mb-2">
          Fill in patient information
        </h2>
      </div>

      {/* Patient Info Form */}
      <form
        onSubmit={handleScan}
        className="max-w-md w-full flex flex-col gap-4 bg-white p-6 rounded-md shadow-md"
      >
        <input
          type="text"
          placeholder="Patient Name"
          value={patientName}
          onChange={(e) => setPatientName(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />
        <input
          type="text"
          placeholder="Patient ID"
          value={patientId}
          onChange={(e) => setPatientId(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-2 focus:ring-darkblue"
          required
        />
        <select
          value={gender}
          onChange={(e) => setGender(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
        >
          <option value="Male">Male</option>
          <option value="Female">Female</option>
        </select>
        <input
          type="number"
          placeholder="Age"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="p-3 rounded-md border border-darkblue focus:outline-none focus:ring-2 focus:ring-darkblue"
          required
        />

        <button
          type="submit"
          className="bg-darkblue text-white font-semibold p-3 rounded-md hover:bg-blue-700 transition-colors"
        >
          Scan
        </button>
      </form>
    </div></div>

  );
};

export default Uploads;
